reference_prolog:
/*  Self-contained SWI-Prolog program answering:

    "Does Utah (2021) eviction law explicitly regulate landlords with minimal rental properties
     (e.g., <=5 single family homes; <=3 homes/rental properties; <=3 condo/co-op units)?"

    Statutes provided are definition sections:
      - UT Code  57-16-3 (2021) (Mobile Home Park Residency Act definitions)
      - UT Code  57-22-2 (2021) (Residential Rental Unit Act definitions)

    These definition provisions do not set any special "small landlord" thresholds.
*/

/* ----------------------------- */
/* Scenario (question) encoding  */
/* ----------------------------- */

scenario_state(utah).
scenario_focus_year(2021).

/* The question's "minimal rental properties" categories to check for explicit regulation. */
small_landlord_category(five_or_fewer_single_family_homes).      % <= 5 SFHs
small_landlord_category(three_or_fewer_homes_or_rentals).        % <= 3 homes/rental props
small_landlord_category(three_or_fewer_condo_or_coop_units).     % <= 3 condo/co-op units

/* Succeeds when the full factual statement (the query being asked) is represented. */
scenario_statement :-
    scenario_state(utah),
    scenario_focus_year(2021),
    small_landlord_category(five_or_fewer_single_family_homes),
    small_landlord_category(three_or_fewer_homes_or_rentals),
    small_landlord_category(three_or_fewer_condo_or_coop_units).

/* ------------------------------------------- */
/* Statute translations (as deterministic rules) */
/* ------------------------------------------- */

/* --- UT Code  57-16-3 (2021): Definitions (Mobile Home Park) --- */
/* (1) "Amenities" means enumerated facilities located at a mobile home park. */
statute_ut_57_16_3_amenity(club_house).
statute_ut_57_16_3_amenity(park).
statute_ut_57_16_3_amenity(playground).
statute_ut_57_16_3_amenity(swimming_pool).
statute_ut_57_16_3_amenity(hot_tub).
statute_ut_57_16_3_amenity(tennis_court).
statute_ut_57_16_3_amenity(basketball_court).

/* (2) "Change of use" means change of use of a mobile home park for a non-rental-of-spaces purpose. */
statute_ut_57_16_3_change_of_use(change_use_of_mobile_home_park_for_non_rental_purpose).

/* (3) "Fees" include other charges incidental to tenancy, including examples. */
statute_ut_57_16_3_fee_type(late_fees).
statute_ut_57_16_3_fee_type(pet_charges).
statute_ut_57_16_3_fee_type(storage_recreational_vehicle_charges).
statute_ut_57_16_3_fee_type(park_facility_use_charges).
statute_ut_57_16_3_fee_type(security_deposits).

/* (4) "Mobile home" definition captured as a structured term. */
statute_ut_57_16_3_mobile_home_definition(mobile_home_is_transportable_structure_with_plumbing_heating_electrical_family_dwelling).

/* (5) "Mobile home park" means any tract where two or more mobile home spaces are leased/offered. */
statute_ut_57_16_3_mobile_home_park_is_tract_with_two_or_more_spaces_leased_or_offered.

minimum_spaces_for_mobile_home_park(2).  % numeric threshold explicitly stated in 57-16-3(5)

/* (6) "Mobile home space" definition. */
statute_ut_57_16_3_mobile_home_space_definition(space_within_park_designed_for_one_mobile_home).

/* (7) "Public utility" includes electrical/gas service providers incl. certain entities. */
statute_ut_57_16_3_public_utility_includes(public_utility_title_54).
statute_ut_57_16_3_public_utility_includes(municipality_title_10).

/* (8) "Rent" means charges paid for privilege of occupying a mobile home space; may include service charges and fees. */
statute_ut_57_16_3_rent_includes(service_charges).
statute_ut_57_16_3_rent_includes(fees).

/* (9) "Resident" means individual who leases/rents space in a mobile home park. */
statute_ut_57_16_3_resident_definition(individual_leases_or_rents_mobile_home_park_space).

/* (10) "Service charges" includes separate charges for utilities/trash/sewage/water combos. */
statute_ut_57_16_3_service_charge_type(electrical_service_improvements).
statute_ut_57_16_3_service_charge_type(gas_service_improvements).
statute_ut_57_16_3_service_charge_type(trash_removal).
statute_ut_57_16_3_service_charge_type(sewage).
statute_ut_57_16_3_service_charge_type(water).

/* (11) "Settlement discussion expiration" definition. */
statute_ut_57_16_3_settlement_discussion_expiration(failed_to_give_written_notice_of_dispute_in_time).
statute_ut_57_16_3_settlement_discussion_expiration(met_but_unsuccessful_resolving_dispute).

/* --- UT Code  57-22-2 (2021): Definitions (Residential Rental Units) --- */
/* (1) "Owner" means owner, lessor, or sublessor; managing/leasing/resident manager considered owner unless specifies otherwise. */
statute_ut_57_22_2_owner_role(owner).
statute_ut_57_22_2_owner_role(lessor).
statute_ut_57_22_2_owner_role(sublessor).
statute_ut_57_22_2_owner_role(managing_agent).
statute_ut_57_22_2_owner_role(leasing_agent).
statute_ut_57_22_2_owner_role(resident_manager).

/* (2) "Rental agreement" means any agreement, written or oral, establishing/modifying terms regarding use/occupancy. */
statute_ut_57_22_2_rental_agreement_definition(any_written_or_oral_agreement_on_terms_conditions_rules_or_other_provisions).

/* (3) "Rental application" definition. */
statute_ut_57_22_2_rental_application_definition(application_required_as_prerequisite_to_enter_rental_agreement).

/* (4) "Renter" definition. */
statute_ut_57_22_2_renter_definition(person_entitled_under_rental_agreement_to_occupy_to_exclusion_of_others).

/* (5) "Residential rental unit" definition and exclusions. */
statute_ut_57_22_2_residential_rental_unit_includes(principal_place_of_residence).
statute_ut_57_22_2_residential_rental_unit_includes(appurtenances).
statute_ut_57_22_2_residential_rental_unit_includes(grounds).
statute_ut_57_22_2_residential_rental_unit_includes(facilities_held_out_for_general_use).
statute_ut_57_22_2_residential_rental_unit_includes(other_area_or_facility_provided_in_agreement).

statute_ut_57_22_2_residential_rental_unit_excludes(boarding_or_rooming_house_facilities).
statute_ut_57_22_2_residential_rental_unit_excludes(mobile_home_lot).
statute_ut_57_22_2_residential_rental_unit_excludes(recreational_property_rented_on_occasional_basis).

/* ------------------------------------------ */
/* Reasoning: does law explicitly regulate "small landlords"? */
/* ------------------------------------------ */

/*
  We model "explicit regulation of landlords with minimal rental properties" as:
  the presence of an explicit numeric threshold or category in the statutes
  that ties landlord duties/rights to owning <=N dwellings/units/homes/properties.

  The provided statutes contain one numeric threshold (>=2 spaces for a mobile home park),
  but they do NOT contain any numeric thresholds about landlord portfolio size (e.g., 3 homes, 5 homes).
*/

/* Identify whether the encoded statutes include any explicit "small landlord" thresholds. */
statute_explicit_small_landlord_threshold(utah, 2021, Category) :-
    % If Utah 2021 law explicitly used Category, it would be represented here.
    % No such clause exists in the provided statutes; therefore this predicate fails.
    small_landlord_category(Category),
    fail.

/* The core legal question predicate: true if explicit small-landlord regulation exists. */
eviction_law_explicitly_regulates_minimal_property_landlords(State, Year) :-
    statute_explicit_small_landlord_threshold(State, Year, _AnyCategory).

/* ------------------------------------------ */
/* Final answer (deterministic)               */
/* ------------------------------------------ */

housing_answer(yes) :-
    scenario_statement,
    eviction_law_explicitly_regulates_minimal_property_landlords(utah, 2021),
    !.
housing_answer(no) :-
    scenario_statement,
    \+ eviction_law_explicitly_regulates_minimal_property_landlords(utah, 2021),
    !.

/* ----------------------------- */
/* Main entrypoint (required)    */
/* ----------------------------- */

main :-
    housing_answer(Result),
    format('housing_answer(~w).~n', [Result]).


:- initialization(main, main).
